  step "Redirect URLs: usuń adresy narzedziownikgp.pl i narzedziownik-gp.vercel.app, zostaw albo dodaj:"
  note "    http://localhost:3000/auth/confirm"
  note "    https://narzedziownik-gp-*.vercel.app/auth/confirm   (podglądy Vercel)"
  note ".env.local i zmienne Preview zostają przy tym projekcie."
  pause "Enter, gdy zapisane."
else
  warn "Pomijam: produkcja nie przeszła sprawdzenia, a stary projekt może jeszcze obsługiwać narzedziownikgp.pl."
